import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product inventory by name. Matches product names case-insensitively and returns the matches as text.',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'The search string to match against product names.',
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1-10). Defaults to 10.',
          },
        },
        required: ['query'],
        additionalProperties: false,
      },
    },
  ];
}

function fail(message) {
  throw new Error(message);
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    fail(`Unknown tool: ${name}`);
  }

  args = args || {};
  const { query, limit } = args;

  if (typeof query !== 'string') {
    fail('query must be a string');
  }

  let limitValue = 10;
  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      fail('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      fail('limit must be between 1 and 10');
    }
    limitValue = limit;
  }

  const needle = query.toLowerCase();
  const matches = products
    .filter((p) => p.name.toLowerCase().includes(needle))
    .slice(0, limitValue);

  const text = matches.length === 0
    ? 'No matching products found.'
    : matches.map((p) => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }],
  };
}

